INSERT INTO itinerary_revisions (id, itinerary_id, version_number, parent_revision_id, milestone_label, change_summary, save_type, snapshot, snapshot_checksum, created_at) VALUES ('aa41e037-1bac-0f94-e68b-cefa0978ab08', 'f370bb3e-cf49-f0e8-9335-bbff058093a0', 1, NULL, 'Imported package content', 'Imported from 05 Days Golden Triangle Tour for Website.docx', 'manual'::revision_save_type, '{"header": {"title": "05 Days Delhi, Agra & Jaipur Tour Package", "subtitle": "Delhi, Agra & Jaipur", "tour_code": "DR076", "duration_label": "04 Night / 05 Days", "alternate_titles": []}, "client": {"title": "Mr", "client_name": "Website Package", "email": null, "email2": null, "phone": null, "adults": 2, "children_5_12": 0, "children_below_5": 0, "rooms": 1, "extra_beds": 0, "travel_date": null, "food_preference": null, "special_requests": null}, "days": [{"day_uuid": "52b72610-8971-0a94-4eae-06000e92d0e8", "day_number": 1, "day_title": "Arrival in Delhi", "alternate_day_titles": [], "day_subtitle": null, "day_theme": "Heritage", "day_description": "Welcome to Delhi! Assume yourself in the vibrant energy of Delhi, a wonderful city where antique history and modernismflawlessly blend. Discover majestic monuments, busymarkets, and a different culinary scene.\nUpon your arrival at the railway station or airport, our representative will greet you warmly. After checking into your hotel, take some time to unwind before we begin exploring the vibrant city of Delhi.\nIn the afternoon, we will visit some of Delhi''s most famous attractions:\nReturn to your hotel for an overnight stay in Delhi.", "start_time": "09:00", "end_time": "18:00", "travel_distance_km": null, "travel_time_minutes": null, "location": "Delhi", "hotel_name": null, "room_category": null, "meal_plan": "CP", "breakfast": false, "lunch": false, "dinner": true, "breakfast_hotels": [null, null], "lunch_hotels": [null, null], "dinner_hotels": [null, null], "epai_plan_only": false, "guest_self_booked_hotel": false, "vehicle_type": "AC Car", "pickup_location": null, "drop_location": null, "guide_required": true, "activities": [{"activity_uuid": "322ec842-6c23-3a5d-427b-874b3847d19d", "sort_order": 0, "title": "Red Fort", "description": "Immerse yourself in splendid past of India.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}, {"activity_uuid": "e5f62006-6002-1e29-6832-bbd57c6f2cdb", "sort_order": 1, "title": "Purana Quila", "description": "Ancient walls that whisper Indian history.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}, {"activity_uuid": "da0aa3bd-cf98-6d7c-a5b7-5b33d103be4c", "sort_order": 2, "title": "Jama Masjid", "description": "Marvel at Islamic cultural magnificence.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}, {"activity_uuid": "0aac12d9-d3aa-52b6-71a1-b2ca08b879a7", "sort_order": 3, "title": "Qutab Minar", "description": "Delhi''s towering legacy and attraction.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}, {"activity_uuid": "7e52ec09-0783-5aec-f14d-7a6fb681eec2", "sort_order": 4, "title": "India Gate", "description": "Pay homage to our fallen heroes.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}, {"activity_uuid": "fbc0098c-480e-ae5d-4d6f-c78e577b5d6a", "sort_order": 5, "title": "Chandni Chowk", "description": "Experience the bustling heart of Delhi.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}, {"activity_uuid": "fe56efb7-9cc4-5da8-798b-0954071e9293", "sort_order": 6, "title": "Lakshmi Narayan Temple", "description": "Find serenity in divine tranquillity.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}], "images": [], "internal_notes": "", "client_notes": "", "operations_notes": "", "status": "planned", "completion_pct": 0, "packing_tips": "", "things_to_carry": []}, {"day_uuid": "068406b9-b279-aa14-3b25-bec29f8edbd4", "day_number": 2, "day_title": "Delhi to Agra", "alternate_day_titles": [], "day_subtitle": null, "day_theme": "Heritage", "day_description": "After a delicious breakfast, we will depart for Agra. Home to the wonderful Taj Mahal, Agra catches attention of visitors with its rich Mughal tradition. Explore grand forts, beautiful gardens, and everlasting architectural wonders.\nUpon checking into your hotel and relaxing for a bit, we will start our exploration of Agra''s highlights:\nOvernight stay at a hotel in Agra.", "start_time": "09:00", "end_time": "18:00", "travel_distance_km": null, "travel_time_minutes": null, "location": "Delhi", "hotel_name": null, "room_category": null, "meal_plan": "CP", "breakfast": true, "lunch": false, "dinner": true, "breakfast_hotels": [null, null], "lunch_hotels": [null, null], "dinner_hotels": [null, null], "epai_plan_only": false, "guest_self_booked_hotel": false, "vehicle_type": "AC Car", "pickup_location": null, "drop_location": null, "guide_required": true, "activities": [{"activity_uuid": "71ed5db3-d7a5-f10d-3a3e-fc7fe123ff0c", "sort_order": 0, "title": "Taj Mahal", "description": "Discover the eternal symbol of love.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}, {"activity_uuid": "c44b5640-4f75-84da-8e15-a8bf55217e12", "sort_order": 1, "title": "Agra Fort", "description": "Explore the grandeur of Mughal architecture.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}, {"activity_uuid": "fc6cf48c-927e-559d-86cd-920746557263", "sort_order": 2, "title": "Itimad-Ud-Daulah", "description": "Admire exquisite marble craftsmanship.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}, {"activity_uuid": "e7020e86-6dbb-392f-c640-a411dc1d161b", "sort_order": 3, "title": "Local markets and bazaars", "description": "Delve into Agra''s vibrant shopping scene.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}], "images": [], "internal_notes": "", "client_notes": "", "operations_notes": "", "status": "planned", "completion_pct": 0, "packing_tips": "", "things_to_carry": []}, {"day_uuid": "0ea7d4ce-349e-356c-3ccf-2ea8d189f223", "day_number": 3, "day_title": "Agra to Jaipur", "alternate_day_titles": [], "day_subtitle": null, "day_theme": "Heritage", "day_description": "After breakfast, we journey to Jaipur. Recognized as the Pink City, Jaipur fascinates with its royal palaces, famous forts, and colorful markets. Experience the royal glory and cultural prosperity of Rajasthan''s capital.\nUpon arrival and hotel check-in, take some time to unwind. In the evening, we will explore the modern attractions of the Pink City:\nStatue Circle - Modern city landmark in stone.\nBirla Auditorium & Planetarium - Celestial insights under modern dome.\nVidhan Sabha - Seat of legislative assembly power.\nBirla Mandir - Marble sanctuary of divine serenity.\nJawahar Kala Kendra - Cultural hub for artistic endeavours.\nConclude the day with a delightful Rajasthani dinner at a resort, accompanied by folk music and traditional dance in a village setting.\nOvernight stay at your hotel in Jaipur.", "start_time": "09:00", "end_time": "18:00", "travel_distance_km": null, "travel_time_minutes": null, "location": "Jaipur", "hotel_name": null, "room_category": null, "meal_plan": "CP", "breakfast": true, "lunch": false, "dinner": true, "breakfast_hotels": [null, null], "lunch_hotels": [null, null], "dinner_hotels": [null, null], "epai_plan_only": false, "guest_self_booked_hotel": false, "vehicle_type": "AC Car", "pickup_location": null, "drop_location": null, "guide_required": false, "activities": [], "images": [], "internal_notes": "", "client_notes": "", "operations_notes": "", "status": "planned", "completion_pct": 0, "packing_tips": "", "things_to_carry": []}, {"day_uuid": "1130d850-bb7a-d906-c1b4-8716082acd0a", "day_number": 4, "day_title": "Jaipur Sightseeing", "alternate_day_titles": [], "day_subtitle": null, "day_theme": "Heritage", "day_description": "After a hearty breakfast, we embark on a tour of Jaipur''s historic Pink City, including:\nIn the evening, witness the magnificent Light & Sound show at Amer Fort, narrating Rajasthan''s rich history.\nOvernight stay at your hotel in Jaipur.", "start_time": "09:00", "end_time": "18:00", "travel_distance_km": null, "travel_time_minutes": null, "location": "Jaipur", "hotel_name": null, "room_category": null, "meal_plan": "CP", "breakfast": true, "lunch": false, "dinner": true, "breakfast_hotels": [null, null], "lunch_hotels": [null, null], "dinner_hotels": [null, null], "epai_plan_only": false, "guest_self_booked_hotel": false, "vehicle_type": "AC Car", "pickup_location": null, "drop_location": null, "guide_required": true, "activities": [{"activity_uuid": "2e45abde-b0e6-347a-d1b3-d05674440962", "sort_order": 0, "title": "Hawa Mahal", "description": "The iconic Palace of Winds.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}, {"activity_uuid": "6c134da5-765a-0abe-e7af-ed9e4aa7d09c", "sort_order": 1, "title": "City Palace", "description": "Residence of Jaipur''s royal family.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}, {"activity_uuid": "cd542aac-2e93-5b9d-a927-4fbfdcdc59bd", "sort_order": 2, "title": "Jantar Mantar (Observatory)", "description": "Explore astronomical marvels.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}, {"activity_uuid": "52c3185b-d0fe-2411-7499-f86f48a181c0", "sort_order": 3, "title": "Jal Mahal", "description": "A palace floating on Man Sagar Lake.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}, {"activity_uuid": "564029c5-cade-7963-2425-7c82be3bcdb5", "sort_order": 4, "title": "Amer Fort", "description": "Discover the ancient hilltop fortress.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}, {"activity_uuid": "8e818927-a1a1-e73d-512b-1a6f69